head.script:
scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof generator1 !== 'undefined') {
        generator1.remove();
    }

    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // Generator 컴포넌트의 자식인 Group 생성
    let grp_comp = $c.gcm.getTestGroup();

    let strGenerator = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strGenerator += '<w2:generator ' +strNameSpace+ ' id="generator1">';        
    strGenerator += '<w2:treeview id="generator1_child" dataType="listed" tooltipGroupClass="false" style="width:200px; background-color:var(--ws-green-500);" ev:onclick="scwin.generator1_child_onclick">';
    strGenerator += '<w2:itemset nodeset="data:gdl_treeview">';
    strGenerator += '<w2:label ref="label"></w2:label>';
    strGenerator += '<w2:value ref="value"></w2:value>';
    strGenerator += '<w2:depth ref="depth"></w2:depth>';
    strGenerator += '<w2:folder ref=""></w2:folder>';
    strGenerator += '<w2:checkbox ref=""></w2:checkbox>';
    strGenerator += '<w2:checkboxDisabled ref=""></w2:checkboxDisabled>';
    strGenerator += '<w2:image ref=""></w2:image>';
    strGenerator += '<w2:iconImage ref=""></w2:iconImage>';
    strGenerator += '<w2:selectedImage ref=""></w2:selectedImage>';
    strGenerator += '<w2:expandedImage ref=""></w2:expandedImage>';
    strGenerator += '<w2:leafImage ref=""></w2:leafImage>';
    strGenerator += '</w2:itemset>';
    strGenerator += '</w2:treeview>';
    strGenerator += '</w2:generator>';



    scwin.generator1 = await $p.dynamicCreate(
        "generator1",
        "generator",
        strGenerator,
        grp_comp    
    );

    scwin.generator1.insertChild();

    // Generator 컴포넌트의 자식이 아닌 컴포넌트 생성
    $c.gcm.createBasicTreeView('', 'ev:onclick="scwin.target1_onclick"');
}
